export function mergeLongform(letter) {
  const extra = [
    ...(LONGFORM[letter.num] || []),
    ...(LONGFORM_DEEP[letter.num] || []),
    ...(LONGFORM_ESSAY[letter.num] || []),
  ];
  if (!extra.length) return letter;
  const sections = [...letter.sections];
  const actionIdx = sections.findIndex(
    (s) =>
      s.type === "ul" ||
      (s.type === "h2" &&
        /this week|steal|run it|your turn|write yours|build your|14-day|get ahead/i.test(s.text))
  );
  const insertAt = actionIdx >= 0 ? actionIdx : sections.length;
  sections.splice(insertAt, 0, ...extra);
  return { ...letter, sections };
}
